const targetUrl = 'https://demo.realworld.show/';
const maxRetries = 3;
const retryDelayMs = 1000;
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
let result = null;
for (let attempt = 1; attempt <= maxRetries; attempt++) {
  const start = Date.now();
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: targetUrl,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 10000,
    });
    const responseTimeMs = Date.now() - start;
    result = {
      url: targetUrl,
      statusCode: response.statusCode,
      responseTimeMs,
      attempt,
      isUp: response.statusCode === 200,
      checkedAt: new Date().toISOString(),
      error: null,
    };
  } catch (err) {
    const responseTimeMs = Date.now() - start;
    result = {
      url: targetUrl,
      statusCode: null,
      responseTimeMs,
      attempt,
      isUp: false,
      checkedAt: new Date().toISOString(),
      error: (err.message || String(err)),
    };
  }
  if (result.isUp || attempt === maxRetries) break;
  await sleep(retryDelayMs);
}

const staticData = $getWorkflowStaticData('global');
staticData.totalChecks = (staticData.totalChecks || 0) + 1;
if (!result.isUp) {
  staticData.downCount = (staticData.downCount || 0) + 1;
}
staticData.sumResponseTimeMs = (staticData.sumResponseTimeMs || 0) + result.responseTimeMs;
staticData.maxResponseTimeMs = Math.max(staticData.maxResponseTimeMs || 0, result.responseTimeMs);
staticData.lastStatusCode = result.statusCode;
staticData.lastCheckedAt = result.checkedAt;

return [{ json: result }];

const staticData = $getWorkflowStaticData('global');
const totalChecks = staticData.totalChecks || 0;
const downCount = staticData.downCount || 0;
const upCount = totalChecks - downCount;
const uptimePct = totalChecks > 0 ? ((upCount / totalChecks) * 100).toFixed(2) : 'N/A';
const avgResponseTimeMs = totalChecks > 0 ? Math.round((staticData.sumResponseTimeMs || 0) / totalChecks) : 0;
const maxResponseTimeMs = staticData.maxResponseTimeMs || 0;

const summary = {
  periodEnd: new Date().toISOString(),
  totalChecks,
  upCount,
  downCount,
  uptimePct,
  avgResponseTimeMs,
  maxResponseTimeMs,
  lastStatusCode: staticData.lastStatusCode || null,
  lastCheckedAt: staticData.lastCheckedAt || null,
};

staticData.totalChecks = 0;
staticData.downCount = 0;
staticData.sumResponseTimeMs = 0;
staticData.maxResponseTimeMs = 0;

return [{ json: summary }];
